/**
 * One thing to update on a site.
 */
export type UpdateItem = {
  /**
   * What to update. `agent` upgrades the WPMgr agent itself over its own
   * dedicated signed channel and behaves differently from the others: it
   * must be the ONLY item in its run (its staged-wave rollout is defined
   * over the whole run), it takes no slug and no version pin, and it has
   * no dry run. Success is established only when the upgraded agent
   * reports its new version back; a scheduled acknowledgement is not
   * success. The channel is off unless the control plane enables it.
   *
   */
  type: "plugin" | "theme" | "core" | "agent";
  /**
   * Plugin/theme slug. Ignored (forced to "core") when type is core; must be omitted when type is agent.
   */
  slug?: string;
  /**
   * Desired version, "latest" or an explicit pin. Defaults to latest.
   * A pin is REJECTED when type is agent: the agent's release manifest
   * only ever points at the published build and the agent refuses to
   * install an older one, so a pin could not be honoured.
   *
   */
  version?: string;
};

/**
 * Request to start a bulk update run. Provide EITHER site_ids OR tag to
 * select target sites (not both).
 *
 */
export type UpdateRunCreate = {
  /**
   * Explicit target site IDs.
   */
  site_ids?: Array<string>;
  /**
   * Target all enrolled sites carrying this tag.
   */
  tag?: string;
  items: Array<UpdateItem>;
  /**
   * When true, do not mutate sites; report what would change.
   */
  dry_run?: boolean;
  /**
   * Optional time to run; omitted/now means immediately.
   */
  schedule_at?: string;
};

export type UpdateTask = {
  id: string;
  run_id: string;
  tenant_id: string;
  site_id: string;
  /**
   * The site's display name, resolved by the server on the run DETAIL
   * read (GET /api/v1/updates/{runId}). Present so a client never has to
   * join a task list against a separately-fetched site list to say which
   * site a task belongs to: every site list in this API is paginated, so
   * that join silently loses site identity on any run wider than one
   * page, for display AND for selection. Empty only if the site row
   * could not be read.
   *
   */
  site_name?: string;
  target_type: "plugin" | "theme" | "core" | "agent";
  target_slug: string;
  desired_version?: string;
  from_version?: string;
  to_version?: string;
  /**
   * `cancelled` means the task was never dispatched because its run was
   * halted first; nothing was sent to the site. Only agent self-update
   * runs can halt.
   *
   */
  status:
    | "pending"
    | "running"
    | "succeeded"
    | "failed"
    | "rolled_back"
    | "skipped"
    | "cancelled";
  /**
   * Whether this task may be named in a retry request
   * (POST /api/v1/updates/runs/{id}/retry). Computed by the server from
   * the task's own terminal-state predicate, so the affordance a client
   * offers and the decision the server makes cannot disagree. A client
   * MUST NOT infer this from `detail` or `error`: those carry
   * agent-authored prose that no client contract covers.
   *
   */
  retryable: boolean;
  /**
   * What happened to this task, on the axis a retry decision turns on.
   * The server computes it; the client renders it.
   *
   * * `never_ran` - terminal, but nothing was ever sent to the site
   * (today: `cancelled`, collateral of a halted run). Nothing on the
   * site changed, so this is the lowest-risk task to retry.
   * * `failed` - the site was contacted and the update did not succeed.
   * * `reverted` - the update applied and was then rolled back, so a
   * retry walks the identical path and may reproduce the identical
   * break.
   * * `skipped` - the control plane declined this target (already up to
   * date, site busy, agent build not upgradeable by this channel).
   * Usually correct, but a stale WordPress transient can report
   * "already current" wrongly, so it stays selectable.
   * * `not_applicable` - `succeeded` (retrying re-touches a working
   * site for nothing) or not finished yet (`pending`/`running`).
   *
   * The intended client default selection is `failed` + `never_ran`:
   * both mean "this never succeeded", and `never_ran` additionally means
   * "and nothing was attempted". `reverted` and `skipped` are
   * selectable but never default-on. `not_applicable` is never
   * selectable.
   *
   */
  retry_class:
    | "never_ran"
    | "failed"
    | "reverted"
    | "skipped"
    | "not_applicable";
  detail?: string;
  error?: string;
  started_at?: string;
  finished_at?: string;
  created_at: string;
  updated_at: string;
};

export type UpdateRun = {
  id: string;
  tenant_id: string;
  created_by?: string;
  /**
   * `halted` is terminal and specific to an agent self-update run: a
   * staged-rollout wave failed to prove itself, so every task the run
   * had not already dispatched was cancelled. It is distinct from
   * `completed`, which would hide the fact that the run was stopped.
   *
   */
  status: "pending" | "running" | "completed" | "halted";
  dry_run: boolean;
  scheduled_at?: string;
  created_at: string;
  updated_at: string;
  /**
   * Total number of tasks in this run. Populated on list responses; absent on the detail GET (tasks array is returned instead).
   */
  task_count?: number;
  /**
   * Number of tasks that reached `succeeded` status.
   */
  succeeded_count?: number;
  /**
   * Number of tasks that reached `failed` or `rolled_back` status.
   */
  failed_count?: number;
  /**
   * Number of distinct sites targeted by this run.
   */
  site_count?: number;
  tasks?: Array<UpdateTask>;
};

export type UpdateRunList = {
  items: Array<UpdateRun>;
};

/**
 * The tasks to retry, named explicitly. There is no implicit server-side
 * default set: the client already knows every task's `retry_class` from
 * the run detail response, so it names the ones it means. A second policy
 * on the server could disagree with the checkboxes the operator saw.
 *
 */
export type UpdateRunRetryRequest = {
  /**
   * Task ids from the run being retried. Repeats are collapsed, so
   * `requested` in the response counts DISTINCT ids. An id that is not a
   * task of this run is reported in `excluded` rather than rejecting the
   * whole request.
   *
   */
  task_ids: Array<string>;
};

/**
 * One requested task that produced no work, and why.
 */
export type UpdateRunRetryExclusion = {
  task_id: string;
  /**
   * The machine value, stable and safe to group or count on.
   *
   * * `not_in_run` - the id is not a task of this run.
   * * `not_retryable` - the task succeeded, or has not finished yet.
   * * `site_not_found` - the site no longer resolves.
   * * `site_not_enrolled` - the site is no longer enrolled, so no signed
   * command can be delivered to it.
   * * `agent_current` - the site already runs the published agent build.
   * This is what fires when the release was reverted mid-incident.
   * * `agent_ineligible` - the site runs the plugin-directory build,
   * which has no self-updater.
   * * `agent_version_unknown` - a version could not be compared, and an
   * unreadable version must never become an upgrade.
   * * `target_in_flight` - this (site, target) already has a pending or
   * running task in another run.
   * * `duplicate_target` - another selected task already retries the
   * same (site, target).
   *
   */
  reason:
    | "not_in_run"
    | "not_retryable"
    | "site_not_found"
    | "site_not_enrolled"
    | "agent_current"
    | "agent_ineligible"
    | "agent_version_unknown"
    | "target_in_flight"
    | "duplicate_target";
  /**
   * The server-authored sentence for this exclusion, including the
   * specifics (which versions, which status). Rendered as-is; a client
   * does not need its own copy table to explain an exclusion.
   *
   */
  message: string;
};

/**
 * Accounts for every requested task: `created` + `len(excluded)` always
 * equals `requested`. If `created` is lower than `requested`, the
 * difference is fully itemised in `excluded` and MUST be surfaced to the
 * operator; a partial commit that looks like a complete one is the failure
 * mode this shape exists to prevent.
 *
 */
export type UpdateRunRetryResult = {
  /**
   * The NEW run. Absent when nothing was created (every requested task
   * was excluded), which is a legitimate outcome and not an error.
   *
   */
  run_id?: string;
  /**
   * Number of DISTINCT task ids in the request.
   */
  requested: number;
  /**
   * Number of tasks in the new run.
   */
  created: number;
  /**
   * Every requested task that produced no task in the new run.
   */
  excluded: Array<UpdateRunRetryExclusion>;
  /**
   * Set when the run exists but a best-effort step after the commit did
   * not go to plan (today: a background job could not be scheduled, so
   * some tasks sit pending until the reaper terminalises them). The run
   * and its tasks are real and visible; surface this alongside them
   * rather than treating the retry as failed.
   *
   */
  warning?: string;
};

/**
 * One task-status transition streamed over SSE.
 */
export type UpdateEvent = {
  run_id: string;
  task_id: string;
  site_id: string;
  target_type: "plugin" | "theme" | "core" | "agent";
  target_slug: string;
  status:
    | "pending"
    | "running"
    | "succeeded"
    | "failed"
    | "rolled_back"
    | "skipped"
    | "cancelled";
  from_version?: string;
  to_version?: string;
  detail?: string;
  run_status: "pending" | "running" | "completed" | "halted";
};

/**
 * One snapshot-progress transition streamed over SSE. Status mirrors the
 * parent snapshot's status at publish time so a subscriber can detect a
 * terminal state (completed/failed) and close the EventSource. Phase
 * values come from the closed `allowedProgressPhases` set on the CP.
 *
 */
export type BackupEvent = {
  snapshot_id: string;
  phase:
    | "queued"
    | "dumping_db"
    | "archiving_files"
    | "encrypting_uploading"
    | "submitting_manifest"
    | "completed"
    | "failed"
    | "stalled"
    | "resumed";
  /**
   * Pass-through of the agent's POST /progress payload (e.g. chunk counters).
   */
  phase_detail?: {
    [key: string]: unknown;
  };
  status: "pending" | "running" | "completed" | "failed";
  ts: string;
};

/**
 * Request to start a backup of a site.
 */
export type BackupCreate = {
  /**
   * What to back up. Defaults to full (files + database).
   */
  kind?: "files" | "db" | "full";
};

export type BackupSnapshot = {
  id: string;
  tenant_id: string;
  site_id: string;
  created_by?: string;
  kind: "files" | "db" | "full";
  status: "pending" | "running" | "completed" | "failed";
  /**
   * The age PUBLIC recipient the chunks were encrypted to (provenance).
   * NEVER a private key; the control plane cannot decrypt backups.
   *
   */
  age_recipient?: string;
  total_size?: number;
  chunk_count?: number;
  /**
   * Kept by the monthly-archive retention rule.
   */
  archived?: boolean;
  error?: string;
  /**
   * M5.6 / ADR-032 phpbu runner progress. Empty `{}` until the runner posts
   * its first phase. Shape:
   * { "phase": "uploading", "phase_detail": {"chunks_done": 17, "chunks_total": 42, ...} }
   * Phases form a closed set (see backup.allowedProgressPhases on the CP).
   *
   */
  progress?: {
    [key: string]: unknown;
  };
  /**
   * Server timestamp of the last progress POST from the runner. Used by
   * the CP's two-tier watchdog (soft stall stamps stalled_at below; hard
   * stall fails the run) and by the frontend to detect a silent runner.
   *
   */
  progress_updated_at?: string;
  /**
   * Set by the CP watchdog when a running backup has gone quiet past the
   * soft threshold but is not yet failed. Cleared on the next proof of
   * life (a presign, manifest submit, or progress POST). Drives the
   * "taking longer than expected" hint; null means healthy.
   *
   */
  stalled_at?: string;
  started_at?: string;
  finished_at?: string;
  created_at: string;
  updated_at: string;
  /**
   * ADR-048 incremental backup. True if this snapshot only stores files
   * changed since its parent; false for full-base snapshots and all
   * pre-m44 rows.
   *
   */
  is_incremental?: boolean;
  /**
   * Position of this snapshot within its incremental chain. 0 is the
   * full base; 1+ are successive incrementals.
   *
   */
  generation?: number;
  /**
   * Groups a full base and its incrementals into one chain. Null for legacy/full-base rows.
   */
  chain_id?: string;
  /**
   * The snapshot this incremental was diffed against. Null for full-base rows.
   */
  parent_snapshot_id?: string;
  /**
   * The full-base snapshot at the root of this chain. Null for legacy/full-base rows.
   */
  base_snapshot_id?: string;
  /**
   * Track C (m49). When true the retention GC will never auto-prune this
   * snapshot. Unlock via DELETE /backups/{snapshotId}/lock to restore
   * normal GC eligibility.
   *
   */
  locked?: boolean;
};

export type BackupSnapshotList = {
  items: Array<BackupSnapshot>;
};

/**
 * Paginated fleet snapshot list.
 */
export type BackupFleetList = {
  items: Array<BackupSnapshot>;
  /**
   * Offset to pass for the next page; null when no further pages.
   */
  next_offset?: number;
};

export type BackupHealthItem = {
  site_id: string;
  site_name: string;
  site_url: string;
  status: "unprotected" | "failed" | "stale" | "in_flight" | "protected";
  last_completed_at?: string;
  last_failed_at?: string;
  latest_size_bytes: number;
  in_flight_count: number;
  schedule_cadence?: string;
  next_run_at?: string;
};

export type BackupHealthList = {
  items: Array<BackupHealthItem>;
};

/**
 * One file (or db dump) in a snapshot, summarized.
 */
export type BackupManifestEntry = {
  path: string;
  entry_kind: "file" | "db" | "plugin" | "theme" | "upload" | "wp-content";
  /**
   * Set for db entries (partial restore-by-table).
   */
  table_name?: string;
  size: number;
  mode?: number;
  /**
   * Number of ordered ciphertext chunks reassembling the path.
   */
  chunk_count: number;
};

export type BackupSnapshotDetail = {
  snapshot: BackupSnapshot;
  entries: Array<BackupManifestEntry>;
};

/**
 * Chain-aware bulk delete request (issue #115). Every requested id is
 * processed independently — a locked, in-flight, dependent, or
 * actively-restoring snapshot in the batch is reported as a skipped
 * result row rather than aborting the whole request.
 *
 */
export type BulkDeleteBackupsRequest = {
  /**
   * Snapshot IDs to delete. 1-100 unique ids per call; duplicates are
   * silently deduplicated before the count is checked. Empty (after
   * dedup) or over 100 is rejected with 400.
   *
   */
  ids: Array<string>;
  /**
   * When true, compute the plan but write nothing (no deletes, no GC, no audit).
   */
  dry_run?: boolean;
};

export type BulkDeleteBackupsResultItem = {
  id: string;
  /**
   * "deleted" — the snapshot was removed (or, in dry_run, WOULD be
   * removed). "skipped" — the snapshot was left in place; see code.
   *
   */
  outcome: "deleted" | "skipped";
  /**
   * Null when outcome=deleted; the skip reason otherwise.
   */
  code?:
    | "snapshot_not_found"
    | "snapshot_in_progress"
    | "snapshot_locked"
    | "chain_has_dependents"
    | "restore_in_progress";
  /**
   * Human-readable explanation of code; null when outcome=deleted.
   */
  message?: string;
};

export type BulkDeleteBackupsCounts = {
  requested: number;
  deleted: number;
  skipped: number;
};

export type BulkDeleteBackupsResponse = {
  dry_run: boolean;
  counts: BulkDeleteBackupsCounts;
  results: Array<BulkDeleteBackupsResultItem>;
  /**
   * Sum of total_size over deleted (or, in dry_run, would-be-deleted)
   * rows. An estimate only — actual space is freed asynchronously by
   * the next retention GC sweep.
   *
   */
  reclaimed_bytes_estimate: number;
};

/**
 * Restore selection. Omit both arrays (or set full=true) for a full
 * restore; provide paths for partial file restore, or db_tables for partial
 * db restore. `components` further restricts the operation to specific
 * backup components ("files" and/or "db"); see field doc below.
 *
 */
export type RestoreCreate = {
  full?: boolean;
  /**
   * Site-relative file paths to restore.
   */
  paths?: Array<string>;
  /**
   * Database table names to restore.
   */
  db_tables?: Array<string>;
  /**
   * Which backup components to restore. When omitted, restores all components in the snapshot. Valid values:
   *
   * - "files"      — broad-strokes alias for ALL file components
   * (plugin + theme + upload + wp-content). Use
   * this for "restore everything except the DB".
   * - "db"         — the database dump.
   * - "plugin"     — wp-content/plugins* only (Track 5).
   * - "theme"      — wp-content/themes* only (Track 5).
   * - "upload"     — wp-content/uploads* only (Track 5).
   * - "wp-content" — everything ELSE under wp-content (mu-plugins,
   * languages, drop-ins, custom dirs — NOT
   * plugins/themes/uploads) (Track 5).
   *
   * Examples — to restore only the database, pass ["db"]. To restore only files, pass ["files"]. To restore both, pass ["files","db"] or omit. To restore only plugins, pass ["plugin"]. To restore plugins + uploads, pass ["plugin","upload"].
   *
   */
  components?: Array<
    "files" | "db" | "plugin" | "theme" | "upload" | "wp-content"
  >;
  /**
   * When true, the agent keeps the pre-restore wp-content tree at .wpmgr-old-files-<id>/ for 24 hours as a manual rollback affordance. When false (default), the agent cleans it up immediately after a successful restore.
   *
   */
  keep_old_files?: boolean;
  /**
   * When set, the agent will rewrite `siteurl` and `home` references from the snapshot's source URLs to this target. When unset, the agent uses the current site's URL (no-op when restoring to the same environment). Required for cross-environment restores (dev->prod, staging->prod). The control plane derives this from the destination Site.URL when the restore is dispatched, so callers typically don't need to set it.
   *
   */
  target_site_url?: string;
};

/**
 * Structured projection of a backup snapshot's SQL dump. Produced either
 * by the agent at backup time (preferred; "source": "agent") or by the
 * control plane's legacy streaming parser (fallback; "source":
 * "cp-legacy"). `truncated: true` indicates the parser hit its CPU/time
 * budget; tables/totals may be incomplete.
 *
 */
export type SqlInspection = {
  /**
   * Report wire-shape version; bump when the JSON shape changes.
   */
  schema_version: number;
  /**
   * Total plaintext bytes scanned from the dump.
   */
  dump_bytes?: number;
  /**
   * Connection-level charset from SET NAMES (e.g. utf8mb4).
   */
  charset?: string;
  /**
   * Default collation declared in CREATE TABLE trailers, if any.
   */
  collation?: string;
  /**
   * Most common table-name prefix (chars up to the first underscore);
   * empty when no consistent prefix could be determined.
   *
   */
  table_prefix?: string;
  /**
   * WordPress db_version from wp_options, when detectable.
   */
  wp_version?: string;
  /**
   * WordPress siteurl from wp_options, when detectable.
   */
  siteurl?: string;
  /**
   * WordPress home from wp_options, when detectable.
   */
  home?: string;
  /**
   * True when a {prefix}options table is present in the dump.
   */
  is_wordpress: boolean;
  /**
   * True when the parser hit its budget before finishing.
   */
  truncated?: boolean;
  /**
   * "agent" — the JSON was produced by the agent at backup time and
   * stored as a snapshot artifact. "cp-legacy" — the CP streamed the
   * dump artifact through its own parser as a fallback.
   *
   */
  source: "agent" | "cp-legacy";
  /**
   * Non-fatal scanner warnings (oversized rows, regex anomalies).
   */
  parser_warnings?: Array<string>;
  /**
   * Per-table inventory; row/byte estimates are best-effort.
   */
  tables: Array<{
    name: string;
    rows_estimate: number;
    bytes_estimate?: number;
    auto_increment?: number;
    charset?: string;
    has_fk?: boolean;
  }>;
  /**
   * When the report was assembled (agent or CP wall clock).
   */
  generated_at: string;
};

export type BackupSchedule = {
  id: string;
  tenant_id: string;
  site_id: string;
  cadence: "hourly" | "every_n_hours" | "daily" | "weekly" | "monthly";
  kind: "files" | "db" | "full";
  enabled: boolean;
  retention_days: number;
  monthly_archive_keep: number;
  /**
   * Hour of day (0-23) in the site timezone at which the backup fires.
   */
  run_hour: number;
  /**
   * Minute (0-59) within the hour at which the backup fires.
   */
  run_minute: number;
  /**
   * Day of week (0=Sun..6=Sat) for weekly cadence; null otherwise.
   */
  day_of_week?: number;
  /**
   * Day of month (1-28, capped) for monthly cadence; null otherwise.
   */
  day_of_month?: number;
  /**
   * Interval in hours for every_n_hours cadence; null otherwise.
   */
  frequency_hours?: number;
  /**
   * Minimum number of snapshots to retain regardless of age.
   */
  keep_last: number;
  /**
   * Beta. When true, scheduled and run-now backups for this site may take incremental snapshots (the control plane auto-decides full base vs increment per ADR-048).
   */
  incremental_enabled: boolean;
  /**
   * Optional override of the default incremental base window (7 days). null means use the default.
   */
  base_window_days?: number;
  /**
   * Read-only. IANA timezone name (or fixed-offset label) resolved from the site's WordPress timezone. Used by the UI to display run times.
   */
  timezone: string;
  /**
   * Read-only. GMT offset in hours (e.g. 5.5 for +05:30) from the site's WordPress settings.
   */
  gmt_offset: number;
  next_run_at: string;
  /**
   * Read-only. The next ~3 scheduled occurrence times (RFC 3339 UTC) for the upcoming-preview strip in the UI.
   */
  next_runs: Array<string>;
  last_run_at?: string;
  created_at: string;
  updated_at: string;
};

/**
 * Create or update a site's backup schedule (daily default).
 */
export type BackupScheduleUpdate = {
  cadence?: "hourly" | "every_n_hours" | "daily" | "weekly" | "monthly";
  kind?: "files" | "db" | "full";
  enabled?: boolean;
  /**
   * Rolling-window retention in days. Defaults to the server policy.
   */
  retention_days?: number;
  /**
   * Number of monthly-archive snapshots to keep beyond the window.
   */
  monthly_archive_keep?: number;
  /**
   * Hour of day (0-23) in the site timezone at which the backup fires.
   */
  run_hour?: number;
  /**
   * Minute (0-59) within the hour at which the backup fires.
   */
  run_minute?: number;
  /**
   * Day of week (0=Sun..6=Sat) for weekly cadence; null otherwise.
   */
  day_of_week?: number;
  /**
   * Day of month (1-28, capped) for monthly cadence; null otherwise.
   */
  day_of_month?: number;
  /**
   * Interval in hours for every_n_hours cadence; null otherwise.
   */
  frequency_hours?: number;
  /**
   * Minimum number of snapshots to retain regardless of age.
   */
  keep_last?: number;
  /**
   * Beta. Take incremental backups on this schedule (and via run-now). The control plane auto-decides full base vs increment.
   */
  incremental_enabled?: boolean;
  /**
   * Optional override of the default incremental base window (7 days). Omit/null to use the default.
   */
  base_window_days?: number;
};

/**
 * Track-A backup scope/exclusion settings for a site (m50). A 404 means
 * no settings row exists — safe defaults apply (all components, no exclusions).
 *
 */
export type SiteBackupSettingsContents = {
  site_id: string;
  /**
   * Subset of archive components to include. Null/absent means all components (full backup).
   * Singular vocabulary matching manifest entry_kind:
   * "plugin" (wp-content/plugins*), "theme" (wp-content/themes*),
   * "upload" (wp-content/uploads*), "wp-content" (catch-all), "db" (database dump),
   * "core" (ABSPATH: wp-admin, wp-includes, root PHP files).
   *
   */
  backup_components?: Array<
    "plugin" | "theme" | "upload" | "wp-content" | "db" | "core"
  >;
  /**
   * When true, the WordPress core source root (ABSPATH) is archived.
   */
  include_core?: boolean;
  /**
   * Path-segment names to exclude from file archiving.
   */
  exclude_paths?: Array<string>;
  /**
   * File extensions to skip (without leading dot, case-insensitive).
   */
  exclude_extensions?: Array<string>;
  /**
   * Skip files strictly larger than this value (MiB). 0/null = no filter.
   */
  exclude_file_size_mb?: number;
  created_at?: string;
  updated_at: string;
};

/**
 * Update the Track-A backup scope/exclusion settings for a site.
 */
export type SiteBackupSettingsContentsUpdate = {
  /**
   * Subset of archive components. Null/absent = all components (full backup).
   */
  backup_components?: Array<
    "plugin" | "theme" | "upload" | "wp-content" | "db" | "core"
  >;
  include_core?: boolean;
  exclude_paths?: Array<string>;
  exclude_extensions?: Array<string>;
  /**
   * 0 or null clears the filter.
   */
  exclude_file_size_mb?: number;
};

/**
 * Track-B notification settings for a site (m50). A 404 means no settings
 * row exists — safe defaults apply (never/empty). Fires for BOTH manual
 * and scheduled backup completions/failures.
 *
 */
export type SiteBackupSettingsNotifications = {
  site_id: string;
  /**
   * When to send a backup-event email. Fires for both manual and
   * scheduled runs. "always" = every completion or failure;
   * "on_failure" = only on failure; "never" = no email (default).
   *
   */
  notify_on_completion: "always" | "on_failure" | "never";
  /**
   * Email addresses to notify. Max 20.
   */
  notify_recipients?: Array<string>;
  created_at?: string;
  updated_at: string;
};

/**
 * Update the Track-B notification settings for a site.
 */
export type SiteBackupSettingsNotificationsUpdate = {
  notify_on_completion?: "always" | "on_failure" | "never";
  notify_recipients?: Array<string>;
};

/**
 * A single restore attempt, created when the operator calls
 * `POST /backups/{snapshotId}/restore`. The run advances through
 * phases as the agent executes the restore; `current_phase` reflects
 * the latest phase received from the agent. `triggered_by_email` and
 * `triggered_by_name` are resolved from the tenant user directory
 * when the actor is a known user; they are `null` for API-key or
 * system-triggered restores.
 *
 */
export type RestoreRun = {
  /**
   * Unique restore run ID.
   */
  id: string;
  /**
   * ID of the site being restored.
   */
  site_id: string;
  /**
   * ID of the backup snapshot used as the restore source.
   */
  snapshot_id: string;
  /**
   * Restore mode. `full` means all components were requested;
   * `partial` means a subset was specified.
   *
   */
  mode: "full" | "partial";
  /**
   * Which backup components were restored (e.g. `files`, `db`).
   */
  components: Array<"files" | "db">;
  /**
   * Current status of the restore run.
   */
  status: "queued" | "running" | "completed" | "failed" | "rolled_back";
  /**
   * The last phase reported by the agent runner (absent when queued).
   */
  current_phase?: string;
  /**
   * Human-readable error message when status is `failed` or `rolled_back`.
   */
  error?: string;
  /**
   * Raw actor identifier (user UUID or `api-key:<id>` or `system`).
   */
  triggered_by?: string;
  /**
   * Email of the triggering user (null for non-user actors or unresolvable IDs).
   */
  triggered_by_email?: string;
  /**
   * Display name of the triggering user (null for non-user actors or unresolvable IDs).
   */
  triggered_by_name?: string;
  /**
   * When the restore run was created.
   */
  created_at: string;
  /**
   * When the agent began executing the restore (absent until running).
   */
  started_at?: string;
  /**
   * When the restore run reached a terminal state.
   */
  finished_at?: string;
};

export type RestoreRunList = {
  items: Array<RestoreRun>;
};

/**
 * A single phase-log entry emitted by the restore engine.
 */
export type RestoreRunEvent = {
  /**
   * Monotonically increasing event ID (use as cursor for `?after=`).
   */
  id: number;
  /**
   * The restore phase that produced this event.
   */
  phase: string;
  /**
   * Outcome of the phase at the time of this event.
   */
  status: "started" | "completed" | "failed";
  /**
   * Optional human-readable detail from the agent.
   */
  message?: string;
  /**
   * Wall-clock time at which the event was recorded.
   */
  occurred_at: string;
};

export type RestoreRunEventList = {
  items: Array<RestoreRunEvent>;
};

/**
 * A single scheduled-backup fire. Pre-inserted as `scheduled` before
 * the run window opens, then advanced to `queued` (dispatched to River),
 * `running` (agent executing), and finally a terminal status
 * (`completed`, `failed`, `skipped`, or `canceled`).
 * `triggered_by_email` and `triggered_by_name` are resolved from the
 * tenant user directory when the actor is a known user (schedule-fired
 * runs carry `triggered_by="schedule"` and leave these null).
 *
 */
export type ScheduleRun = {
  /**
   * Unique schedule run ID.
   */
  id: string;
  /**
   * ID of the site this run targets.
   */
  site_id: string;
  /**
   * ID of the backup schedule that generated this run.
   */
  schedule_id: string;
  /**
   * ID of the backup snapshot created by this run (absent until the snapshot is created).
   */
  snapshot_id?: string;
  /**
   * The scheduled fire time for this run.
   */
  scheduled_for: string;
  /**
   * Current status of the schedule run.
   */
  status:
    | "scheduled"
    | "queued"
    | "running"
    | "completed"
    | "failed"
    | "skipped"
    | "canceled";
  /**
   * Backup kind that will be (or was) created by this run.
   */
  kind: "full" | "incremental";
  /**
   * Human-readable error message when status is `failed`.
   */
  error?: string;
  /**
   * Actor that triggered this run (`schedule` for automatic fires; user UUID for manual).
   */
  triggered_by?: string;
  /**
   * Email of the triggering user (null for schedule-fired or unresolvable actors).
   */
  triggered_by_email?: string;
  /**
   * Display name of the triggering user (null for schedule-fired or unresolvable actors).
   */
  triggered_by_name?: string;
  /**
   * When the schedule run row was created.
   */
  created_at: string;
  /**
   * When the run transitioned to `running` (absent until then).
   */
  started_at?: string;
  /**
   * When the run reached a terminal state.
   */
  finished_at?: string;
};

/**
 * Split view of schedule runs for a site. `upcoming` contains
 * non-terminal runs (bounded to 10); `past` contains terminal runs
 * (paginated). One or both lists may be empty.
 *
 */
export type ScheduleRunList = {
  /**
   * Non-terminal schedule runs (scheduled/queued/running), newest-fire-time first.
   */
  upcoming: Array<ScheduleRun>;
  /**
   * Terminal schedule runs (completed/failed/skipped/canceled), newest first.
   */
  past: Array<ScheduleRun>;
};

/**
 * Windowed uptime status for a single site (from the metrics store).
 */
export type UptimeStatus = {
  site_id: string;
  window: "7d" | "30d" | "90d";
  /**
   * Percentage of checks in the window that were up (0-100).
   */
  uptime_pct: number;
  /**
   * Mean total request time over the window, in milliseconds.
   */
  avg_latency_ms: number;
  /**
   * Number of probe checks recorded in the window.
   */
  checks: number;
  /**
   * Whether the most recent probe classified the site as up.
   */
  up: boolean;
  /**
   * Time of the most recent probe (absent if never probed).
   */
  last_check?: string;
  /**
   * Leaf TLS certificate expiry from the latest probe (HTTPS only).
   */
  tls_expiry?: string;
  /**
   * Downsampled per-bucket check series over the window.
   */
  series: Array<UptimePoint>;
};

export type UptimePoint = {
  /**
   * Start of the time bucket.
   */
  bucket: string;
  checks: number;
  up_checks: number;
  avg_latency_ms: number;
};

export type UptimeSummary = {
  items: Array<UptimeSummaryItem>;
};

export type FleetUptimeCounts = {
  up: number;
  degraded: number;
  down: number;
  unknown: number;
};

export type FleetUptimeStatusItem = {
  site_id: string;
  site_name: string;
  site_url: string;
  status: "up" | "degraded" | "down" | "unknown";
  /**
   * Short machine-readable explanation for status, populated when
   * status=degraded (agent_unreachable, agent_degraded, app_down, or
   * slow_response). Empty/absent when the status needs no further
   * explanation.
   *
   */
  status_reason?: string;
  uptime_pct_7d: number;
  avg_latency_ms_7d: number;
  latest_total_ms?: number;
  last_probe_at?: string;
  tls_expiry?: string;
  in_incident: boolean;
  connection_state: string;
  health_status: string;
  /**
   * GH #291 Phase 2 application-health verdict from the most recent
   * app probe: true (WordPress responded), false (conclusively
   * down), or absent/null (never probed, or the most recent probe
   * was inconclusive; see app_probe_reason). Independent of `up`
   * (the reachability signal, unchanged forever): a cached 200
   * (up=true) can coexist with app_up=false when a page cache is
   * masking a dead PHP backend.
   *
   */
  app_up?: boolean;
  /**
   * Machine-readable reason for the most recent app-health verdict
   * (agent_fresh, rest_ok, rest_5xx, wp_fatal_error, cache_hit,
   * rest_forbidden, rest_absent, rest_4xx, rest_non_json,
   * unreachable, rest_unexpected). Empty when no app probe has run
   * yet.
   *
   */
  app_probe_reason?: string;
};

