/**
 * One frame in a PHP error backtrace (most-recent-call-first).
 */
export type PhpErrorFrame = {
  /**
   * Absolute path to the PHP file containing the call.
   */
  file: string;
  /**
   * Line number of the call site.
   */
  line: number;
  /**
   * Function or method name at this frame (empty string for file-level code).
   */
  function: string;
};

export type PhpError = {
  /**
   * The CP-side row UUID (stringified).
   */
  id: string;
  /**
   * The agent-side dedup fingerprint (md5(code:file:line:message)).
   */
  md5: string;
  /**
   * PHP error code (E_* constant value).
   */
  code: number;
  /**
   * One of fatal, warning, notice, deprecated, bootstrap, unknown.
   */
  severity: string;
  message: string;
  file: string;
  line: number;
  request_path: string;
  first_seen_at: string;
  last_seen_at: string;
  occurrence_count: number;
  silenced: boolean;
  /**
   * Up to 10 stack frames captured at the error site, most-recent-call-first. Always present; may be an empty array for errors captured before S1.1 or when the agent could not produce a trace.
   *
   */
  backtrace: Array<PhpErrorFrame>;
};

export type PhpErrorList = {
  items: Array<PhpError>;
  next_cursor?: string;
};

export type PhpErrorSilence = {
  /**
   * Whether to silence (default true).
   */
  silenced?: boolean;
};

export type SiteErrorConfig = {
  /**
   * Whether PHP-error capture is active for this site.
   *
   */
  enabled?: boolean;
  /**
   * PHP E_* bitmask the agent applies to wp_debug_log collection.
   * Default 6143 = E_ALL & ~E_STRICT (WordPress default).
   *
   */
  error_level: number;
  /**
   * Ordered list of 32-character lowercase hex md5 fingerprints
   * (md5(code:file:line:message)) the agent must suppress without
   * counting or reporting. An empty list clears all suppression.
   *
   */
  ignore_md5s: Array<string>;
};

export type SiteErrorConfigUpdate = {
  /**
   * Turns PHP-error capture on or off. OMITTING this field is treated as
   * true: a client that does not know about the flag can never
   * accidentally disable the mu-plugin trap, but that also means an
   * update sent without it re-enables capture on a site where it was
   * switched off. Send false explicitly to keep capture disabled.
   *
   */
  enabled?: boolean;
  /**
   * PHP E_* bitmask to apply. Must be >0 and fit in int32.
   *
   */
  error_level: number;
  /**
   * Full canonical ignore-list (replaces the stored list atomically).
   * Each entry must be exactly 32 lowercase hex characters.
   *
   */
  ignore_md5s: Array<string>;
};

export type SiteActivityEvent = {
  /**
   * The CP-side row id (stringified BIGSERIAL).
   */
  id: string;
  /**
   * Agent-assigned monotonic sequence within the chain.
   */
  seq: number;
  event_type: string;
  object_type: string;
  object_id: string;
  object_label: string;
  /**
   * WP user id of the actor; 0 for system events.
   */
  actor_user_id: number;
  /**
   * WP login of the actor; empty for system events.
   */
  actor_login: string;
  actor_ip: string;
  summary: string;
  /**
   * Agent-supplied event metadata (severity lives here).
   */
  meta: {
    [key: string]: unknown;
  };
  severity: "high" | "medium" | "low";
  /**
   * The prior link's hash (64 zero chars at genesis).
   */
  prev_hash: string;
  /**
   * sha256 over the canonical event preimage.
   */
  this_hash: string;
  /**
   * Server-verified at ingest. False marks a tampered/broken link: the
   * CP-recomputed hash did not match the shipped this_hash, or the
   * shipped prev_hash did not match the prior stored row.
   *
   */
  chain_valid: boolean;
  occurred_at: string;
  received_at: string;
};

export type SiteActivityList = {
  items: Array<SiteActivityEvent>;
  next_cursor?: string;
};

export type ActivityVerifyResult = {
  /**
   * True when the entire chain re-verifies intact.
   */
  valid: boolean;
  /**
   * The seq of the first broken link, or null when the chain is intact.
   * Kept for backward compatibility; equals break.seq when broken.
   *
   */
  break_at_seq?: number;
  /**
   * Total number of events folded during verification.
   */
  total: number;
  /**
   * Null when the chain is intact. Describes the first broken link with
   * enough detail for an operator to understand and act on the failure.
   *
   */
  break?: ChainBreak;
};

export type ChainBreak = {
  /**
   * The seq of the event where verification failed.
   */
  seq: number;
  /**
   * Classifies the break:
   * - missing_events: one or more seq numbers are absent (log cleanup / retention / deletion).
   * - link_mismatch: contiguous seq but prev_hash broken (insertion/removal/reorder/prior alteration).
   * - content_modified: prev link intact but recomputed hash diverges (content edited after recording).
   * - chain_start_missing: first stored event does not chain from genesis (oldest events gone / chain reset).
   *
   */
  kind:
    | "missing_events"
    | "link_mismatch"
    | "content_modified"
    | "chain_start_missing";
  /**
   * The seq of the last successfully-verified row. Null when the break is
   * at the first/genesis row and no prior row was verified.
   *
   */
  prior_seq?: number;
  /**
   * Number of missing sequence numbers between prior_seq and seq.
   * 0 when contiguous or when there is no prior row.
   *
   */
  seq_gap: number;
  /**
   * The verified chain head before this row: the prior row's this_hash,
   * or GenesisPrevHash (64 zero hex chars) if this is the first row.
   *
   */
  expected_prev_hash: string;
  /**
   * The row's own prev_hash as stored.
   */
  stored_prev_hash: string;
  /**
   * ComputeHashFromStored(expected_prev_hash, row).
   */
  recomputed_this_hash: string;
  /**
   * The row's own this_hash as stored.
   */
  stored_this_hash: string;
  /**
   * The offending event fields for operator context.
   */
  event: {
    summary: string;
    event_type: string;
    actor_login: string;
    occurred_at: string;
  };
};

export type SecurityThresholds = {
  /**
   * Number of failures before a CAPTCHA challenge is shown.
   */
  captcha_limit: number;
  /**
   * Number of failures before a temporary block is applied.
   */
  temp_block_limit: number;
  /**
   * Number of failures before a permanent block is applied.
   */
  block_all_limit: number;
  /**
   * Seconds of inactivity that reset the failure counter.
   *
   */
  failed_login_gap: number;
  /**
   * Seconds after a successful login before a new failure series begins.
   *
   */
  success_login_gap: number;
  /**
   * Seconds a permanent block remains active.
   */
  all_blocked_gap: number;
};

export type SiteLoginProtectionConfig = {
  /**
   * Login protection mode:
   * - `disabled` — no login protection active.
   * - `audit` — record events but do not block.
   * - `protect` — record events AND block based on thresholds.
   *
   */
  mode: "disabled" | "audit" | "protect";
  thresholds: SecurityThresholds;
  /**
   * HTTP header the agent reads to extract the real client IP (e.g.
   * `REMOTE_ADDR`, `HTTP_X_FORWARDED_FOR`).
   *
   */
  ip_header: string;
  /**
   * CIDRs that always bypass all checks (IPv4 or IPv6, with prefix length).
   *
   */
  allow_cidrs: Array<string>;
  /**
   * CIDRs that are always denied before threshold evaluation.
   *
   */
  deny_cidrs: Array<string>;
  /**
   * When the config was last saved. Absent for the built-in default.
   */
  updated_at?: string;
};

export type SiteLoginProtectionConfigUpdate = {
  /**
   * Login protection mode.
   */
  mode: "disabled" | "audit" | "protect";
  thresholds: SecurityThresholds;
  /**
   * HTTP header the agent reads for the real client IP.
   */
  ip_header: string;
  /**
   * CIDRs always allowed. Empty = no static allowlist. When mode=protect
   * and this list is empty the CP auto-adds the operator's IP (/32 or /128).
   *
   */
  allow_cidrs: Array<string>;
  /**
   * CIDRs always denied before threshold evaluation. Empty = none.
   */
  deny_cidrs: Array<string>;
};

