export type CreateSiteData = {
  body: SiteCreate;
  path?: never;
  query?: never;
  url: "/api/v1/sites";
};

export type CreateSiteErrors = {
  /**
   * Site URL already exists for this tenant. The `details` object carries
   * `site_id` (UUID string) and `connection_state` (string) of the
   * existing row so the web can branch: offer "Cancel and re-add" when
   * `pending_enrollment`, "Reconnect" when `archived`/`disconnected`,
   * or a generic "already exists" message otherwise.
   *
   */
  409: Error & {
    details?: {
      /**
       * ID of the existing site with this URL.
       */
      site_id: string;
      /**
       * Current connection state of the existing site.
       */
      connection_state:
        | "pending_enrollment"
        | "connected"
        | "degraded"
        | "disconnected"
        | "revoked"
        | "archived";
    };
  };
  /**
   * Validation failed
   */
  422: Error;
};

export type CreateSiteError = CreateSiteErrors[keyof CreateSiteErrors];

export type CreateSiteResponses = {
  /**
   * Site created (pending_enrollment) with a once-shown enrollment code
   */
  201: SiteEnrollmentCode;
};

export type CreateSiteResponse = CreateSiteResponses[keyof CreateSiteResponses];

